Add PPPoE dissectors").

Here is the patch:
  */
 bool __skb_flow_dissect(const struct net *net,
 			const struct sk_buff *skb,
 			struct flow_dissector *flow_dissector,
 			void *target_container, const void *data,
 			__be16 proto, int nhoff, int hlen, unsigned int flags)
 {
 	struct flow_dissector_key_control *key_control;
 	struct flow_dissector_key_basic *key_basic;
 	struct flow_dissector_key_addrs *key_addrs;
 	struct flow_dissector_key_tags *key_tags;
 	struct flow_dissector_key_vlan *key_vlan;
 	enum flow_dissect_ret fdret;
 	enum flow_dissector_key_id dissector_vlan = FLOW_DISSECTOR_KEY_MAX;
 	bool mpls_el = false;
 	int mpls_lse = 0;
 	int num_hdrs = 0;
 	u8 ip_proto = 0;
 	bool ret;

 	if (!data) {
 		data = skb->data;
 		proto = skb_vlan_tag_present(skb) ?
 			 skb->vlan_proto : skb->protocol;
 		nhoff = skb_network_offset(skb);
 		hlen = skb_headlen(skb);
 #if IS_ENABLED(CONFIG_NET_DSA)
 		if (unlikely(skb->dev && netdev_uses_dsa(skb->dev) &&
 			     proto == htons(ETH_P_XDSA))) {
 			struct metadata_dst *md_dst = skb_metadata_dst(skb);
 			const struct dsa_device_ops *ops;
 			int offset = 0;

 			ops = skb->dev->dsa_ptr->tag_ops;
 			/* Only DSA header taggers break flow dissection */
 			if (ops->needed_headroom &&
 			    (!md_dst || md_dst->type != METADATA_HW_PORT_MUX)) {
 				if (ops->flow_dissect)
 					ops->flow_dissect(skb, &proto, &offset);
 				else
 					dsa_tag_generic_flow_dissect(skb,
 								     &proto,
 								     &offset);
 				hlen -= offset;
 				nhoff += offset;
 			}
 		}
 #endif
 	}

 	/* It is ensured by skb_flow_dissector_init() that control key will
 	 * be always present.
 	 */
 	key_control = skb_flow_dissector_target(flow_dissector,
 						FLOW_DISSECTOR_KEY_CONTROL,
 						target_container);

 	/* It is ensured by skb_flow_dissector_init() that basic key will
 	 * be always present.
 	 */
 	key_basic = skb_flow_dissector_target(flow_dissector,
 					      FLOW_DISSECTOR_KEY_BASIC,
 					      target_container);

 	rcu_read_lock();

 	if (skb) {
 		if (!net) {
 			if (skb->dev)
 				net = dev_net_rcu(skb->dev);
 			else if (skb->sk)
 				net = sock_net(skb->sk);
 		}
 	}

 	DEBUG_NET_WARN_ON_ONCE(!net);
 	if (net) {
 		enum netns_bpf_attach_type type = NETNS_BPF_FLOW_DISSECTOR;
 		struct bpf_prog_array *run_array;

 		run_array = rcu_dereference(init_net.bpf.run_array[type]);
 		if (!run_array)
 			run_array = rcu_dereference(net->bpf.run_array[type]);

 		if (run_array) {
 			struct bpf_flow_keys flow_keys;
 			struct bpf_flow_dissector ctx = {
 				.flow_keys = &flow_keys,
 				.data = data,
 				.data_end = data + hlen,
 			};
 			__be16 n_proto = proto;
 			struct bpf_prog *prog;
 			u32 result;

 			if (skb) {
 				ctx.skb = skb;
 				/* we can't use 'proto' in the skb case
 				 * because it might be set to skb->vlan_proto
 				 * which has been pulled from the data
 				 */
 				n_proto = skb->protocol;
 			}

 			prog = READ_ONCE(run_array->items[0].prog);
 			result = bpf_flow_dissect(prog, &ctx, n_proto, nhoff,
 						  hlen, flags);
 			if (result != BPF_FLOW_DISSECTOR_CONTINUE) {
 				__skb_flow_bpf_to_target(&flow_keys, flow_dissector,
 							 target_container);
 				rcu_read_unlock();
 				return result == BPF_OK;
 			}
 		}
 	}

 	rcu_read_unlock();

 	if (dissector_uses_key(flow_dissector,
 			       FLOW_DISSECTOR_KEY_ETH_ADDRS)) {
 		struct ethhdr *eth = eth_hdr(skb);
 		struct flow_dissector_key_eth_addrs *key_eth_addrs;

 		key_eth_addrs = skb_flow_dissector_target(flow_dissector,
 							  FLOW_DISSECTOR_KEY_ETH_ADDRS,
 							  target_container);
 		memcpy(key_eth_addrs, eth, sizeof(*key_eth_addrs));
 	}

 	if (dissector_uses_key(flow_dissector,
 			       FLOW_DISSECTOR_KEY_NUM_OF_VLANS)) {
 		struct flow_dissector_key_num_of_vlans *key_num_of_vlans;

 		key_num_of_vlans = skb_flow_dissector_target(flow_dissector,
 							     FLOW_DISSECTOR_KEY_NUM_OF_VLANS,
 							     target_container);
 		key_num_of_vlans->num_of_vlans = 0;
 	}

 proto_again:
 	fdret = FLOW_DISSECT_RET_CONTINUE;

 	switch (proto) {
 	case htons(ETH_P_IP): {
 		const struct iphdr *iph;
 		struct iphdr _iph;

 		iph = __skb_header_pointer(skb, nhoff, sizeof(_iph), data, hlen, &_iph);
 		if (!iph || iph->ihl < 5) {
 			fdret = FLOW_DISSECT_RET_OUT_BAD;
 			break;
 		}

 		nhoff += iph->ihl * 4;

 		ip_proto = iph->protocol;

 		if (dissector_uses_key(flow_dissector,
 				       FLOW_DISSECTOR_KEY_IPV4_ADDRS)) {
 			key_addrs = skb_flow_dissector_target(flow_dissector,
 							      FLOW_DISSECTOR_KEY_IPV4_ADDRS,
 							      target_container);

 			memcpy(&key_addrs->v4addrs.src, &iph->saddr,
 			       sizeof(key_addrs->v4addrs.src));
 			memcpy(&key_addrs->v4addrs.dst, &iph->daddr,
 			       sizeof(key_addrs->v4addrs.dst));
 			key_control->addr_type = FLOW_DISSECTOR_KEY_IPV4_ADDRS;
 		}

 		__skb_flow_dissect_ipv4(skb, flow_dissector,
 					target_container, data, iph);

 		if (ip_is_fragment(iph)) {
 			key_control->flags |= FLOW_DIS_IS_FRAGMENT;

 			if (iph->frag_off & htons(IP_OFFSET)) {
 				fdret = FLOW_DISSECT_RET_OUT_GOOD;
 				break;
 			} else {
 				key_control->flags |= FLOW_DIS_FIRST_FRAG;
 				if (!(flags &
 				      FLOW_DISSECTOR_F_PARSE_1ST_FRAG)) {
 					fdret = FLOW_DISSECT_RET_OUT_GOOD;
 					break;
 				}
 			}
 		}

 		break;
 	}
 	case htons(ETH_P_IPV6): {
 		const struct ipv6hdr *iph;
 		struct ipv6hdr _iph;

 		iph = __skb_header_pointer(skb, nhoff, sizeof(_iph), data, hlen, &_iph);
 		if (!iph) {
 			fdret = FLOW_DISSECT_RET_OUT_BAD;
 			break;
 		}

 		ip_proto = iph->nexthdr;
 		nhoff += sizeof(struct ipv6hdr);

 		if (dissector_uses_key(flow_dissector,
 				       FLOW_DISSECTOR_KEY_IPV6_ADDRS)) {
 			key_addrs = skb_flow_dissector_target(flow_dissector,
 							      FLOW_DISSECTOR_KEY_IPV6_ADDRS,
 							      target_container);

 			memcpy(&key_addrs->v6addrs.src, &iph->saddr,
 			       sizeof(key_addrs->v6addrs.src));
 			memcpy(&key_addrs->v6addrs.dst, &iph->daddr,
 			       sizeof(key_addrs->v6addrs.dst));
 			key_control->addr_type = FLOW_DISSECTOR_KEY_IPV6_ADDRS;
 		}

 		if ((dissector_uses_key(flow_dissector,
 					FLOW_DISSECTOR_KEY_FLOW_LABEL) ||
 		     (flags & FLOW_DISSECTOR_F_STOP_AT_FLOW_LABEL)) &&
 		    ip6_flowlabel(iph)) {
 			__be32 flow_label = ip6_flowlabel(iph);

 			if (dissector_uses_key(flow_dissector,
 					       FLOW_DISSECTOR_KEY_FLOW_LABEL)) {
 				key_tags = skb_flow_dissector_target(flow_dissector,
 								     FLOW_DISSECTOR_KEY_FLOW_LABEL,
 								     target_container);
 				key_tags->flow_label = ntohl(flow_label);
 			}
 			if (flags & FLOW_DISSECTOR_F_STOP_AT_FLOW_LABEL) {
 				fdret = FLOW_DISSECT_RET_OUT_GOOD;
 				break;
 			}
 		}

 		__skb_flow_dissect_ipv6(skb, flow_dissector,
 					target_container, data, iph);

 		break;
 	}
 	case htons(ETH_P_8021AD):
 	case htons(ETH_P_8021Q): {
 		const struct vlan_hdr *vlan = NULL;
 		struct vlan_hdr _vlan;
 		__be16 saved_vlan_tpid = proto;

 		if (dissector_vlan == FLOW_DISSECTOR_KEY_MAX &&
 		    skb && skb_vlan_tag_present(skb)) {
 			proto = skb->protocol;
 		} else {
 			vlan = __skb_header_pointer(skb, nhoff, sizeof(_vlan),
 						    data, hlen, &_vlan);
 			if (!vlan) {
 				fdret = FLOW_DISSECT_RET_OUT_BAD;
 				break;
 			}

 			proto = vlan->h_vlan_encapsulated_proto;
 			nhoff += sizeof(*vlan);
 		}

 		if (dissector_uses_key(flow_dissector, FLOW_DISSECTOR_KEY_NUM_OF_VLANS) &&
 		    !(key_control->flags & FLOW_DIS_ENCAPSULATION)) {
 			struct flow_dissector_key_num_of_vlans *key_nvs;

 			key_nvs = skb_flow_dissector_target(flow_dissector,
 							    FLOW_DISSECTOR_KEY_NUM_OF_VLANS,
 							    target_container);
 			key_nvs->num_of_vlans++;
 		}

 		if (dissector_vlan == FLOW_DISSECTOR_KEY_MAX) {
 			dissector_vlan = FLOW_DISSECTOR_KEY_VLAN;
 		} else if (dissector_vlan == FLOW_DISSECTOR_KEY_VLAN) {
 			dissector_vlan = FLOW_DISSECTOR_KEY_CVLAN;
 		} else {
 			fdret = FLOW_DISSECT_RET_PROTO_AGAIN;
 			break;
 		}

 		if (dissector_uses_key(flow_dissector, dissector_vlan)) {
 			key_vlan = skb_flow_dissector_target(flow_dissector,
 							     dissector_vlan,
 							     target_container);

 			if (!vlan) {
 				key_vlan->vlan_id = skb_vlan_tag_get_id(skb);
 				key_vlan->vlan_priority = skb_vlan_tag_get_prio(skb);
 			} else {
 				key_vlan->vlan_id = ntohs(vlan->h_vlan_TCI) &
 					VLAN_VID_MASK;
 				key_vlan->vlan_priority =
 					(ntohs(vlan->h_vlan_TCI) &
 					 VLAN_PRIO_MASK) >> VLAN_PRIO_SHIFT;
 			}
 			key_vlan->vlan_tpid = saved_vlan_tpid;
 			key_vlan->vlan_eth_type = proto;
 		}

 		fdret = FLOW_DISSECT_RET_PROTO_AGAIN;
 		break;
 	}
 	case htons(ETH_P_PPP_SES): {
 		struct {
 			struct pppoe_hdr hdr;
 			__be16 proto;
 		} *hdr, _hdr;
 		u16 ppp_proto;

 		hdr = __skb_header_pointer(skb, nhoff, sizeof(_hdr), data, hlen, &_hdr);
 		if (!hdr) {
 			fdret = FLOW_DISSECT_RET_OUT_BAD;
 			break;
 		}

 		if (!is_pppoe_ses_hdr_valid(&hdr->hdr)) {
 			fdret = FLOW_DISSECT_RET_OUT_BAD;
 			break;
 		}

-		/* least significant bit of the most significant octet
-		 * indicates if protocol field was compressed
+		/* PFC (compressed 1-byte protocol) frames are not processed.
+		 * A compressed protocol field has the least significant bit of
+		 * the most significant octet set, which will fail the following
+		 * ppp_proto_is_valid(), returning FLOW_DISSECT_RET_OUT_BAD.
 		 */
 		ppp_proto = ntohs(hdr->proto);
-		if (ppp_proto & 0x0100) {
-			ppp_proto = ppp_proto >> 8;
-			nhoff += PPPOE_SES_HLEN - 1;
-		} else {
-			nhoff += PPPOE_SES_HLEN;
-		}
+		nhoff += PPPOE_SES_HLEN;

 		if (ppp_proto == PPP_IP) {
 			proto = htons(ETH_P_IP);
 			fdret = FLOW_DISSECT_RET_PROTO_AGAIN;
 		} else if (ppp_proto == PPP_IPV6) {
 			proto = htons(ETH_P_IPV6);
 			fdret = FLOW_DISSECT_RET_PROTO_AGAIN;
 		} else if (ppp_proto == PPP_MPLS_UC) {
 			proto = htons(ETH_P_MPLS_UC);
 			fdret = FLOW_DISSECT_RET_PROTO_AGAIN;
 		} else if (ppp_proto == PPP_MPLS_MC) {
 			proto = htons(ETH_P_MPLS_MC);
 			fdret = FLOW_DISSECT_RET_PROTO_AGAIN;
 		} else if (ppp_proto_is_valid(ppp_proto)) {
 			fdret = FLOW_DISSECT_RET_OUT_GOOD;
 		} else {
 			fdret = FLOW_DISSECT_RET_OUT_BAD;
 			break;
 		}

 		if (dissector_uses_key(flow_dissector,
 				       FLOW_DISSECTOR_KEY_PPPOE)) {
 			struct flow_dissector_key_pppoe *key_pppoe;

 			key_pppoe = skb_flow_dissector_target(flow_dissector,
 							      FLOW_DISSECTOR_KEY_PPPOE,
 							      target_container);
 			key_pppoe->session_id = hdr->hdr.sid;
 			key_pppoe->ppp_proto = htons(ppp_proto);
 			key_pppoe->type = htons(ETH_P_PPP_SES);
 		}
 		break;
 	}
 	case htons(ETH_P_TIPC): {
 		struct tipc_basic_hdr *hdr, _hdr;

 		hdr = __skb_header_pointer(skb, nhoff, sizeof(_hdr),
 					   data, hlen, &_hdr);
 		if (!hdr) {
 			fdret = FLOW_DISSECT_RET_OUT_BAD;
 			break;
 		}

 		if (dissector_uses_key(flow_dissector,
 				       FLOW_DISSECTOR_KEY_TIPC)) {
 			key_addrs = skb_flow_dissector_target(flow_dissector,
 							      FLOW_DISSECTOR_KEY_TIPC,
 							      target_container);
 			key_addrs->tipckey.key = tipc_hdr_rps_key(hdr);
 			key_control->addr_type = FLOW_DISSECTOR_KEY_TIPC;
 		}
 		fdret = FLOW_DISSECT_RET_OUT_GOOD;
 		break;
 	}

 	case htons(ETH_P_MPLS_UC):
 	case htons(ETH_P_MPLS_MC):
 		fdret = __skb_flow_dissect_mpls(skb, flow_dissector,
 						target_container, data,
 						nhoff, hlen, mpls_lse,
 						&mpls_el);
 		nhoff += sizeof(struct mpls_label);
 		mpls_lse++;
 		break;
 	case htons(ETH_P_FCOE):
 		if ((hlen - nhoff) < FCOE_HEADER_LEN) {
 			fdret = FLOW_DISSECT_RET_OUT_BAD;
 			break;
 		}

 		nhoff += FCOE_HEADER_LEN;
 		fdret = FLOW_DISSECT_RET_OUT_GOOD;
 		break;

 	case htons(ETH_P_ARP):
 	case htons(ETH_P_RARP):
 		fdret = __skb_flow_dissect_arp(skb, flow_dissector,
 					       target_container, data,
 					       nhoff, hlen);
 		break;

 	case htons(ETH_P_BATMAN):
 		fdret = __skb_flow_dissect_batadv(skb, key_control, data,
 						  &proto, &nhoff, hlen, flags);
 		break;

 	case htons(ETH_P_1588): {
 		struct ptp_header *hdr, _hdr;

 		hdr = __skb_header_pointer(skb, nhoff, sizeof(_hdr), data,
 					   hlen, &_hdr);
 		if (!hdr) {
 			fdret = FLOW_DISSECT_RET_OUT_BAD;
 			break;
 		}

 		nhoff += sizeof(struct ptp_header);
 		fdret = FLOW_DISSECT_RET_OUT_GOOD;
 		break;
 	}

 	case htons(ETH_P_PRP):
 	case htons(ETH_P_HSR): {
 		struct hsr_tag *hdr, _hdr;

 		hdr = __skb_header_pointer(skb, nhoff, sizeof(_hdr), data, hlen,
 					   &_hdr);
 		if (!hdr) {
 			fdret = FLOW_DISSECT_RET_OUT_BAD;
 			break;
 		}

 		proto = hdr->encap_proto;
 		nhoff += HSR_HLEN;
 		fdret = FLOW_DISSECT_RET_PROTO_AGAIN;
 		break;
 	}

 	case htons(ETH_P_CFM):
 		fdret = __skb_flow_dissect_cfm(skb, flow_dissector,
 					       target_container, data,
 					       nhoff, hlen);
 		break;

 	default:
 		fdret = FLOW_DISSECT_RET_OUT_BAD;
 		break;
 	}

 	/* Process result of proto processing */
 	switch (fdret) {
 	case FLOW_DISSECT_RET_OUT_GOOD:
 		goto out_good;
 	case FLOW_DISSECT_RET_PROTO_AGAIN:
 		if (skb_flow_dissect_allowed(&num_hdrs))
 			goto proto_again;
 		goto out_good;
 	case FLOW_DISSECT_RET_CONTINUE:
 	case FLOW_DISSECT_RET_IPPROTO_AGAIN:
 		break;
 	case FLOW_DISSECT_RET_OUT_BAD:
 	default:
 		goto out_bad;
 	}

 ip_proto_again:
 	fdret = FLOW_DISSECT_RET_CONTINUE;

 	switch (ip_proto) {
 	case IPPROTO_GRE:
 		if (flags & FLOW_DISSECTOR_F_STOP_BEFORE_ENCAP) {
 			fdret = FLOW_DISSECT_RET_OUT_GOOD;
 			break;
 		}

 		fdret = __skb_flow_dissect_gre(skb, key_control, flow_dissector,
 					       target_container, data,
 					       &proto, &nhoff, &hlen, flags);
 		break;

 	case NEXTHDR_HOP:
 	case NEXTHDR_ROUTING:
 	case NEXTHDR_DEST: {
 		u8 _opthdr[2], *opthdr;

 		if (proto != htons(ETH_P_IPV6))
 			break;

 		opthdr = __skb_header_pointer(skb, nhoff, sizeof(_opthdr),
 					      data, hlen, &_opthdr);
 		if (!opthdr) {
 			fdret = FLOW_DISSECT_RET_OUT_BAD;
 			break;
 		}

 		ip_proto = opthdr[0];
 		nhoff += (opthdr[1] + 1) << 3;

 		fdret = FLOW_DISSECT_RET_IPPROTO_AGAIN;
 		break;
 	}
 	case NEXTHDR_FRAGMENT: {
 		struct frag_hdr _fh, *fh;

 		if (proto != htons(ETH_P_IPV6))
 			break;

 		fh = __skb_header_pointer(skb, nhoff, sizeof(_fh),
 					  data, hlen, &_fh);

 		if (!fh) {
 			fdret = FLOW_DISSECT_RET_OUT_BAD;
 			break;
 		}

 		key_control->flags |= FLOW_DIS_IS_FRAGMENT;

 		nhoff += sizeof(_fh);
 		ip_proto = fh->nexthdr;

 		if (!(fh->frag_off & htons(IP6_OFFSET))) {
 			key_control->flags |= FLOW_DIS_FIRST_FRAG;
 			if (flags & FLOW_DISSECTOR_F_PARSE_1ST_FRAG) {
 				fdret = FLOW_DISSECT_RET_IPPROTO_AGAIN;
 				break;
 			}
 		}

 		fdret = FLOW_DISSECT_RET_OUT_GOOD;
 		break;
